131	export default function HomePage() {
132	  const [currentPage, setCurrentPage] = useState(0); // 目前分頁狀態（從第 0 頁開始）
133	  const [latestAnalyzedCourses, setLatestAnalyzedCourses] = useState<
134	    LatestLessonCardItem[]
135	  >([]);
136	  const [lastUpdatedAt, setLastUpdatedAt] = useState<string | null>(null);
137	  const itemsPerPage = 4;
138	  const totalPages = Math.ceil(NOTIFICATIONS.length / itemsPerPage); // 計算總頁數（以 {itemsPerPage} 則通知為一頁）
139	
140	  useEffect(() => {
141	    const fetchLatestLessons = async () => {
142	      try {
143	        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
144	        const response = await fetch(`${basePath}/api/lessons/latest?limit=4`, {
145	          method: "GET",
146	          headers: { accept: "*/*" },
147	        });
148	
149	        if (!response.ok) {
150	          throw new Error("Failed to fetch latest lessons");
151	        }
152	
153	        const resBody = await response.json();
154	        const lessons = Array.isArray(resBody?.lessons) ? resBody.lessons : [];
155	        const mappedLessons = lessons.map(
156	          (lesson: LatestLessonApiItem): LatestLessonCardItem => ({
157	            name: lesson.course_name,
158	            date: formatDate(lesson.generated_at),
159	            course_key: lesson.course_key,
160	            course_id: lesson.course_id,
161	            class: lesson.course_section,
162	            schedule: formatCourseSchedule(lesson.course_schedule),
163	            lesson_id: lesson.lesson_id,
164	            generated_at: lesson.generated_at,
165	          }),
166	        );
167	
168	        setLatestAnalyzedCourses(mappedLessons);
169	        setLastUpdatedAt(lessons[0]?.generated_at ?? null);
170	      } catch (error) {
171	        console.error(error);
172	      }
173	    };
174	
175	    fetchLatestLessons();
176	  }, []);
177	
178	  // 當使用者拉大螢幕時，自動把分頁歸零，避免 RWD 切換時出錯
179	  useEffect(() => {
180	    const handleResize = () => {
181	      if (window.innerWidth >= 1024) {
182	        setCurrentPage(0);
183	      }
184	    };
185	    window.addEventListener("resize", handleResize);
186	    return () => window.removeEventListener("resize", handleResize);
187	  }, []);
188	
189	  // 根據目前頁數，裁切出要顯示的通知
190	  const startIndex = currentPage * itemsPerPage;
191	  const pagedNotifications = NOTIFICATIONS.slice(
192	    startIndex,
193	    startIndex + itemsPerPage,
194	  );
195	
196	  const [activeNotification, setActiveNotification] = useState<
197	    (typeof NOTIFICATIONS)[0] | null
198	  >(null);
199	
200	  return (
201	    <div className="flex min-h-screen bg-[#F2F2F2] text-slate-700 font-sans">
202	      <main className="flex-1 p-4 md:p-8 flex flex-col lg:flex-row gap-6 items-stretch">
203	        <div className="flex-1 lg:flex-[3] flex flex-col gap-4 lg:max-h-[calc(100vh-64px)]">
204	          <section className="relative h-[326px] rounded-[24px] p-10 flex flex-col justify-center overflow-hidden shrink-0">
205	            <Image
206	              src="/images/img_banner-w.svg"
207	              alt="Banner Background"
208	              fill
209	              priority
210	              className="object-cover object-right z-0 hidden md:block"
211	            />
212	            <Image
213	              src="/images/img_banner-m.svg"
214	              alt="Banner Background"
215	              fill
216	              priority
217	              className="object-cover object-right z-0 md:hidden"
218	            />
219	            <div className="relative">
220	              <h1 className="large-title-1 mb-2 text-gray-90">
221	                Good morning, 庭妤
222	              </h1>
223	              <p className="body-1-reg text-slate-600">
224	                {lastUpdatedAt
225	                  ? `資料上次更新時間：${formatFullDate(lastUpdatedAt).replace(
226	                      /(\d+)年(\d+)月(\d+)日/,
227	                      "$1 年 $2 月 $3 日",
228	                    )}`
229	                  : "資料上次更新時間：—"}
230	              </p>
231	            </div>
232	          </section>
233	
234	          <div className="grid grid-cols-[1.2fr_1fr] max-md:grid-cols-1 gap-4 flex-1 max-h-[calc(100vh-326px)] max-md:max-h-none overflow-hidden">
235	            <DataCard
236	              title="最新分析"
237	              data={latestAnalyzedCourses}
238	              hasChart
239	              sortByField="date"
240	              sortOrder="desc"
241	            />
242	            <DataCard
243	              title="近期查看"
244	              data={RECENTLY_VIEWED_COURSES}
245	              hasLastCheckedAt
246	              sortByField="last_checked_at"
247	              sortOrder="desc"
248	            />
249	          </div>
250	        </div>
251	        <aside className="w-full lg:w-auto lg:flex-1 bg-[rgba(6,45,65,0.05)] rounded-[32px] p-6 flex flex-col lg:max-h-[calc(100vh-64px)] lg:sticky lg:top-8">
252	          {/* TODO: 顯示未讀通知數量 */}
253	          <h2 className="headline-3-sb text-gray-90">通知中心 (1)</h2>
254	          <div className="flex justify-end mb-2">
255	            {/* TODO: 全部標記為已讀功能 */}
256	            <button className="body-2-reg text-blue-70 underline cursor-pointer">
257	              全部標記為已讀
258	            </button>
259	          </div>
260	          <div className="flex-1 overflow-x-auto lg:overflow-y-auto space-y-2 pr-1 custom-scrollbar">
261	            {/* 在 lg 以上顯示「全部通知」；lg 以下只顯示「裁切後的該頁通知」 */}
262	            <div className="hidden lg:block space-y-2">
263	              {NOTIFICATIONS.map((n) => (
264	                <NotificationItem
265	                  key={n.id}
266	                  date={n.date}
267	                  type={n.type as "system" | "update" | "personal" | "general"}
268	                  content={n.content}
269	                  onClick={() =>
270	                    setActiveNotification(n as (typeof NOTIFICATIONS)[0])
271	                  }
272	                  isNew={n.isNew}
273	                />
274	              ))}
275	            </div>
276	
277	            <div className="block lg:hidden space-y-2">
278	              {pagedNotifications.map((n) => (
279	                <NotificationItem
280	                  key={n.id}
281	                  date={n.date}
282	                  type={n.type as "system" | "update" | "personal" | "general"}
283	                  content={n.content}
284	                  onClick={() =>
285	                    setActiveNotification(n as (typeof NOTIFICATIONS)[0])
286	                  }
287	                  isNew={n.isNew}
288	                />
289	              ))}
290	            </div>
291	            {totalPages > 1 && (
292	              <div className="flex lg:hidden justify-center items-center gap-2 mt-4">
293	                {Array.from({ length: totalPages }).map((_, index) => {
294	                  const isActive = index === currentPage;
295	                  return (
296	                    <button
297	                      key={index}
298	                      type="button"
299	                      onClick={() => setCurrentPage(index)}
300	                      className={`transition-all duration-300 rounded-full cursor-pointer focus:outline-none ${
301	                        isActive
302	                          ? "w-4 h-1.5 bg-blue-70"
303	                          : "w-1.5 h-1.5 bg-gray-300 hover:bg-gray-400"
304	                      }`}
305	                      aria-label={`Go to page ${index + 1}`}
306	                    />
307	                  );
308	                })}
309	              </div>
310	            )}
311	          </div>
312	        </aside>
313	      </main>
314	      {activeNotification && (
315	        <NotificationDialog
316	          isOpen={activeNotification !== null}
317	          onClose={() => setActiveNotification(null)}
318	          title={notificationConfig[activeNotification.type].title}
319	          date={activeNotification.date}
320	          icon={notificationConfig[activeNotification.type].icon}
321	          content={activeNotification.content}
322	        />
323	      )}
324	    </div>
325	  );
326	}
