19	export default function CourseAnalyticsPage() {
20	  const [selectedGroup, setSelectedGroup] = useState("class");
21	  const [chartHoverSeconds, setChartHoverSeconds] = useState<number | null>(
22	    null,
23	  );
24	  const { courseKey, lessonId } = useParams();
25	  const [lessonDetail, setLessonDetail] = useState<any>(null);
26	  const [playbackSeconds, setPlaybackSeconds] = useState<number>(0);
27	  const [videoUrl, setVideoUrl] = useState<string>(""); // TODO: 這是暫時的影片網址
28	  const videoPlayerRef = useRef<VideoPlayerHandle>(null);
29	  const chartScrollRef = useRef<HTMLDivElement>(null);
30	  const [keyframePreviewEl, setKeyframePreviewEl] =
31	    useState<HTMLDivElement | null>(null);
