46	      } else {
47	        console.error(
48	          `No mock video/audio data found for lessonId: ${lessonId}`,
49	        );
50	      }
51	    }
52	  };
53	
54	  // 由於 DB 資料不一致，先把 groups 的 key 值從 T1 改成 G1 ...
55	  const normalizeGroupKeys = (groups: Record<string, any> = {}) =>
56	    Object.keys(groups).reduce(
57	      (acc, key) => {
58	        const newKey = key.replace(/^T/, "G");
59	        acc[newKey] = groups[key];
60	        return acc;
61	      },
62	      {} as Record<string, any>,
63	    );
64	
65	  const fetchLessonDetail = async () => {
66	    try {
67	      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
68	      const response = await fetch(`${basePath}/api/lessons/${lessonId}`);
69	      if (!response.ok) throw new Error("Failed to fetch lesson detail");
70	      const resBody = await response.json();
71	      resBody.result.groups = normalizeGroupKeys(resBody.result.groups);
72	      setLessonDetail((prev: any) => ({
73	        ...resBody,
74	        metadata: {
75	          ...prev?.metadata,
76	          ...resBody?.metadata,
77	        },
78	      }));
79	      console.log("Fetched lesson detail from API");
80	    } catch (error) {
81	      console.error(error);
82	      // const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
83	      // const mockDataPath = `${basePath}${mockAiResultMapping[lessonId as keyof typeof mockAiResultMapping]}`;
84	      // if (mockDataPath) {
85	      //   fetch(mockDataPath).then((res: any) => {
86	      //     if (!res.ok)
87	      //       throw new Error(`Failed to load mock JSON: ${res.status}`);
88	      //     return res
89	      //       .json()
90	      //       .then((resBody: any) => {
91	      //         resBody.result.groups = normalizeGroupKeys(resBody.result.groups);
92	      //         return resBody;
93	      //       })
94	      //       .then((jsonData: any) => {
95	      //         setLessonDetail(jsonData);
96	      //         console.log("Successfully loaded mock JSON data:", jsonData);
97	      //       })
98	      //       .catch((err: any) => {
99	      //         console.error("Error reading mock JSON file:", err);
100	      //       });
101	      //   });
102	      // } else {
103	      //   console.error(`No mock AI result found for lessonId: ${lessonId}`);
104	      // }
105	    }
106	  };
107	
108	  useEffect(() => {
109	    if (!lessonId || lessonId === "undefined") return;
110	    fetchVideo();
111	    fetchLessonDetail();
112	  }, [lessonId]);
113	
114	  const fetchCourseDetail = async () => {
115	    try {
116	      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
117	      const response = await fetch(
118	        `${basePath}/api/courses/${courseKey}/lessons`,
119	      );
120	
121	      if (!response.ok) throw new Error("Failed to fetch course detail");
122	      const resBody = await response.json();
123	
124	      const lesson = resBody.lessons.find((item: any) => {
125	        return (
126	          decodeURIComponent(item.lesson_id) ===
127	          decodeURIComponent(lessonId as string)
128	        );
129	      });
130	      setLessonDetail((prevDetail: any) => ({
131	        ...prevDetail,
132	        metadata: {
133	          ...prevDetail?.metadata,
134	          course_name: resBody.course_name,
135	          topic: lesson?.topic,
136	          status: lesson?.status,
137	          lesson_date: lesson?.lesson_date,
138	        },
139	      }));
140	      console.log("Fetched course detail from API");
141	    } catch (error) {
142	      console.error(error);
143	    }
144	  };
145	
146	  useEffect(() => {
147	    if (!courseKey || courseKey === "undefined") return;
148	    fetchCourseDetail();
149	  }, [courseKey]);
150	
151	  // 初始化時間格式化器
152	  const toTaiwanHHMM = useMemo(() => {
153	    const startTime = lessonDetail?.metadata?.generated_at || "";
154	    return createTaiwanTimeFormatter(startTime);
155	  }, [lessonDetail?.metadata?.generated_at]);
156	
157	  // 計算指標
158	  const metrics = useMemo(() => {
159	    // 根據 SeatMap 的選取狀況動態決定資料來源（全班數據 or 某小組數據）
160	    const currentData =
161	      selectedGroup === "class"
162	        ? lessonDetail?.result?.class || []
163	        : lessonDetail?.result?.groups?.[selectedGroup] || [];
164	
165	    if (!currentData.length) {
166	      return { avgList: [], maxTimeList: [], minTimeList: [] };
167	    }
168	
169	    const chartData = buildChartData(currentData, toTaiwanHHMM);
170	    const totalPoints = chartData.length;
171	    const extrema = findModeExtrema(chartData);
172	
173	    const avgList = MODE_CONFIGS.map((mode) => {
174	      const sum = chartData.reduce(
175	        (acc, point) => acc + (point[mode.key] ?? 0),
176	        0,
177	      );
178	      return (sum / totalPoints).toFixed(1);
179	    });
180	
181	    const maxTimeList = MODE_CONFIGS.map(
182	      (mode) => extrema[mode.key]?.max.name ?? "--",
183	    );
184	    const minTimeList = MODE_CONFIGS.map(
185	      (mode) => extrema[mode.key]?.min.name ?? "--",
186	    );
187	
188	    return { avgList, maxTimeList, minTimeList };
189	  }, [lessonDetail, selectedGroup, toTaiwanHHMM]);
