201	      />
202	      <AnalysisMetricCard
203	        variant="time"
204	        label={
205	          <div className="title-2">
206	            佔比<span className="text-success-40">最高</span>時段
207	          </div>
208	        }
209	        subLabel="各自進行"
210	        valueList={metrics.maxTimeList}
211	      />
212	      <AnalysisMetricCard
213	        variant="time"
214	        label={
215	          <div className="title-2">
216	            佔比<span className="text-danger-40">最低</span>時段
217	          </div>
218	        }
219	        subLabel="各自進行"
220	        valueList={metrics.minTimeList}
221	      />
222	    </>
223	  );
224	
225	  return (
226	    <div className="min-h-screen bg-[rgba(242,242,242,1)] p-8 font-sans">
