19	function formatRelativeTime(dateString: string): string {
20	  if (!dateString) return "";
21	
22	  const formattedString = dateString.replace(/-/g, "/");
23	  const date = new Date(formattedString);
24	  const now = new Date();
25	
26	  const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);
27	
28	  if (diffInSeconds < 0) return "剛剛";
29	  if (diffInSeconds < 60) return "剛剛";
30	
31	  const diffInMinutes = Math.floor(diffInSeconds / 60);
32	  if (diffInMinutes < 60) return `${diffInMinutes} 分鐘前`;
33	
34	  const diffInHours = Math.floor(diffInMinutes / 60);
35	  if (diffInHours < 24) return `${diffInHours} 小時前`;
36	
37	  const diffInDays = Math.floor(diffInHours / 24);
38	  if (diffInDays < 7) return `${diffInDays} 天前`;
39	
40	  const diffInWeeks = Math.floor(diffInDays / 7);
41	  if (diffInWeeks < 4) return `${diffInWeeks} 週前`;
42	
43	  const diffInMonths = Math.floor(diffInDays / 30);
44	  if (diffInMonths < 12) return `${diffInMonths} 個月前`;
45	
46	  return `${Math.floor(diffInDays / 365)} 年前`;
47	}
